        try { values.push({ path: 'album.releaseDate', value: parseImportDate({ year: proposal.releaseDate.year, month: proposal.releaseDate.month, day: proposal.releaseDate.day }), slotId: null }); }
        catch { flagged.push({ path: 'album.releaseDate', reason: 'format' }); }
