        const release = candidate?.details === 'fetched' ? candidate.release : null; if (!release) continue;
        const proposal = proposalForRelease(release);
        for (const entry of proposal.artists) if (entry.musicBrainzId) ids.push({ kind: 'artist', id: entry.musicBrainzId });
        if (proposal.labelMusicBrainzId) ids.push({ kind: 'organization', id: proposal.labelMusicBrainzId });
