    // or the label without one).
    const earlier: { path: ImportDraftPath; entryKey: string | null; musicBrainzId: string }[] = [];
    for (const item of Array.isArray(previous?.musicBrainzIds) ? previous!.musicBrainzIds : []) {
        if (!isRecord(item) || typeof item.musicBrainzId !== 'string' || (item.entryKey !== null && typeof item.entryKey !== 'string')) continue;
        const member = review && typeof item.entryKey === 'string' && isLookupValuePath(item.path, { review: true }) && isEntryListPath(item.path) ? item.path : null;
        earlier.push({ path: member ?? (item.entryKey === null ? 'album.label' : 'album.artists'), entryKey: item.entryKey, musicBrainzId: item.musicBrainzId });
    }
    // A review compares and keys a candidate's entries against its draft without the IDs an earlier application supplied, as the
    // review captured them: an entry agrees through the ID its Artist keeps, never through one lookup added.
    const basis = review ? structuredClone(draft) : draft;
    if (review) for (const { path, entryKey, musicBrainzId } of earlier) {
        const current = valueAt(basis, path);
        if (current && entryKey === null && isRecord(current.value) && current.value.musicBrainzId === musicBrainzId) setDraftValue(basis, path, { ...current.value, musicBrainzId: null });
        if (current && entryKey !== null && Array.isArray(current.value)) {
            setDraftValue(basis, path, current.value.map(entry => isRecord(entry) && entry.key === entryKey && entry.musicBrainzId === musicBrainzId ? { ...entry, musicBrainzId: null } : entry));
        }
    }
