            // not. Decisions bind only the Album's entries and the label.
            const bound = member ? undefined : decisions.find(decision => isRecord(decision) && decision.preselected !== true && decision.boundMusicBrainzId === item.musicBrainzId
                && (item.entryKey === null ? decision.scope === 'label' : decision.scope === 'artist' && decision.entryKey === item.entryKey));
            if (bound && bound.boundBy !== 'lookup') continue;
