    // remove the ID again); any other decision on that entry is removed.
    let kept = decisions;
    for (const addition of added) {
        const holder = context.identity.holders.get(`${addition.kind}:${addition.id}`);
        kept = kept.filter(decision => {
            if (!isRecord(decision) || (decision.boundMusicBrainzId ?? null) !== null || decision.boundName !== addition.name
                || (addition.entryKey === null ? decision.scope !== 'label' : decision.scope !== 'artist' || decision.entryKey !== addition.entryKey)) return true;
            const recordKey = `${addition.kind}:${decision.candidateId}`;
            const valid = decision.action === 'reuse' ? holder === decision.candidateId || (holder === undefined && context.identity.storedIds.has(recordKey) && context.identity.storedIds.get(recordKey) === null)
                : decision.action === 'create-distinct' && holder === undefined;
            if (valid) { decision.boundMusicBrainzId = addition.id; decision.boundBy = 'lookup'; }
            return valid;
        });
    }
    const result = applyAutomaticValues({ draft, draftOrigins: origins }, automatic, { introduce }, review ? { cappedDraft: catalogReviewCappedDraft } : {});
    // An automatic value this application did not rewrite (skipped as changed, invalid or over the cap) still loses the earlier IDs.
    removeEarlierIds(new Set(result.written));
    // An emptied value is never marked automatic: it is simply empty again.
    for (const path of result.written) if (emptyValue(draftValueAt(draft, path))) delete origins[originKey(path)];
    const flagged: LookupValueFlag[] = [...supplied.flagged];
    for (const skip of result.skipped) {
        if (suppliedPaths.has(skip.path) && (skip.reason === 'size' || skip.reason === 'invalid')) flagged.push({ path: skip.path, reason: skip.reason === 'size' ? 'size' : 'format' });
    }
    const values: LookupAppliedValue[] = [];
    for (const item of supplied.values) {
        const current = valueAt(draft, item.path);
        if (current && originOf(origins, item.path) === 'automatic' && sameDraftValue(current.value, item.value)) values.push({ path: item.path, value: structuredClone(current.value), slotId: item.slotId });
    }
    // An extended list is recorded as it now stands, so the next application restores it only while it is still as written.
    for (const item of extended) values.push({ ...item, value: structuredClone(draftValueAt(draft, item.path)) });
    // The IDs the draft now carries that this candidate supplied, so the next application can remove them again; a review never
    // records one its draft carried as captured, so another candidate never removes an ID the Artist or label keeps.
    // A review's items each name their path; an import's keep their shape (an Album entry by key, the label without one).
    const supplies = (path: ImportDraftPath, entryKey: string | null, id: string) => !review || !captured(path, entryKey, id);
    const musicBrainzIds: NonNullable<LookupApplication['musicBrainzIds']> = [
        ...draft.album.artists.filter(entry => entry.musicBrainzId && offered.get(entry.key) === entry.musicBrainzId && supplies('album.artists', entry.key, entry.musicBrainzId))
            .map(entry => ({ ...(review ? { path: 'album.artists' as const } : {}), entryKey: entry.key as string | null, musicBrainzId: entry.musicBrainzId! })),
        ...(draft.album.label?.musicBrainzId && offered.get(LABEL) === draft.album.label.musicBrainzId && supplies('album.label', null, draft.album.label.musicBrainzId)
            ? [{ ...(review ? { path: 'album.label' as const } : {}), entryKey: null, musicBrainzId: draft.album.label.musicBrainzId }] : [])];
